/**
 * Unit tests for MathArrays.sortInPlace
 */
public class MathArrays_sortInPlace_TriageGen1Test {













    @Test
    public void testSortInPlaceWithDuplicates() throws NullArgumentException, DimensionMismatchException {
        double[] x = {2.0, 1.0, 2.0};
        double[] y = {10.0, 20.0, 30.0};

        // Increasing order: 1.0, 2.0, 2.0
        // The stability of Collections.sort ensures indices are handled correctly
        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, y);

        assertArrayEquals(new double[]{1.0, 2.0, 2.0}, x, 1e-10);
        // Possible valid outputs for y depending on stability: [20, 10, 30] or [20, 30, 10]
        // Given Pair(2.0, 0) and Pair(2.0, 2), Collections.sort is stable.
        // list will have: (1.0, 1), (2.0, 0), (2.0, 2)
        // indices will be: 1, 0, 2
        // y[0] = yOrig[1] = 20.0
        // y[1] = yOrig[0] = 10.0
        // y[2] = yOrig[2] = 30.0
        assertArrayEquals(new double[]{20.0, 10.0, 30.0}, y, 1e-10);
    }


}

